import { expect, it } from "vitest";
import {
  type ResourceLiveState,
  type LiveSnapshot,
  asResourceKey,
  asRobloxAssetId,
  compareLiveState,
  type ResourceCurrentState,
  asSha256Hex,
} from '@bedrock-rbx/core'

it('Example 1', () => {
  const live: ResourceLiveState<'gamePass'> = {
    kind: 'gamePass',
    outputs: {},
    price: undefined,
  }
  expect('price' in live).toBe(true)
  expect('iconFileHashes' in live).toBe(false)
})

it('Example 2', () => {
  const snapshot: LiveSnapshot = { gamePass: new Map() }
  expect(snapshot.gamePass?.size).toBe(0)
  expect(snapshot.badge).toBeUndefined()
})

it('Example 3', () => {
  const saved: ResourceCurrentState<'developerProduct'> = {
    key: asResourceKey('gems'),
    kind: 'developerProduct',
    name: 'Gems',
    description: '100 gems',
    price: 100,
    outputs: { productId: asRobloxAssetId('123') },
  }
  const compared = compareLiveState([saved], {
    developerProduct: new Map([
      [
        saved.outputs.productId,
        {
          kind: 'developerProduct',
          outputs: {},
          price: 120,
        },
      ],
    ]),
  })
  expect(compared.edits).toEqual([
    {
      key: 'gems',
      kind: 'developerProduct',
      fields: [{ field: 'price', current: 100, live: 120 }],
    },
  ])
  expect(compared.resources).toEqual([{ ...saved, price: 120 }])
  expect(compared.missing).toEqual([])
  expect(saved.price).toBe(100)
})

it('A readable missing icon still needs restoration even when its file is unchanged.', () => {
  const saved: ResourceCurrentState<'badge'> = {
    key: asResourceKey('winner'),
    kind: 'badge',
    name: 'Winner',
    description: 'Win a round',
    enabled: true,
    icon: { 'en-us': 'winner.png' },
    iconFileHashes: { 'en-us': asSha256Hex('a'.repeat(64)) },
    outputs: {
      badgeId: asRobloxAssetId('123'),
      iconImageId: asRobloxAssetId('456'),
    },
  }
  const compared = compareLiveState([saved], {
    badge: new Map([
      [
        saved.outputs.badgeId,
        {
          kind: 'badge',
          outputs: { iconImageId: undefined },
        },
      ],
    ]),
  })
  expect(compared.edits[0]!.fields).toEqual([
    { field: 'icon', current: '456', live: undefined },
  ])
  expect(compared.resources[0]).toEqual(saved)
})
